// CRATE PUSH — Sokoban with puzzles generated by playing backwards (always solvable).
// Params: w, h, boxes, pulls, walls (interior wall chance), levels
import { ArcadeGame, module, COL, DIR, rect, block, irand, pick } from './kit.js';

class Sokoban extends ArcadeGame {
  init() { this.controls = 'D-PAD PUSH  B UNDO  SELECT RESTART'; this.bg = '#1a1410'; }
  reset() { this.level = 1; this.build(); }
  build() {
    for (let tries = 0; tries < 400; tries++) if (this.generate(tries)) break;
    this.history = []; this.moves = 0;
    this.start = JSON.stringify({ p: this.p, boxes: this.boxes });
  }
  generate(tries = 0) {
    const w = (this.v.w || 8) + Math.min(3, this.level - 1), h = this.v.h || 8;
    this.w = w; this.h = h;
    const wall = Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => (x === 0 || y === 0 || x === w - 1 || y === h - 1 ? 1 : 0)));
    for (let y = 2; y < h - 2; y++) for (let x = 2; x < w - 2; x++) if (Math.random() < (tries > 40 ? 0.03 : this.v.walls ?? 0.12)) wall[y][x] = 1;
    const floor = [];
    for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) if (!wall[y][x]) floor.push([x, y]);
    const nBox = (this.v.boxes || 3) + Math.floor((this.level - 1) / 2);
    if (floor.length < nBox + 6) return false;
    const pickFree = (used) => { for (let i = 0; i < 200; i++) { const c = pick(floor); if (!used.some((u) => u[0] === c[0] && u[1] === c[1])) return c; } return null; };
    const goals = [];
    for (let i = 0; i < nBox; i++) { const c = pickFree(goals); if (!c) return false; goals.push(c); }
    const boxes = goals.map((g) => [...g]);
    let p = pickFree(boxes); if (!p) return false;
    const isBox = (x, y) => boxes.findIndex((b) => b[0] === x && b[1] === y);
    const free = (x, y) => !wall[y][x] && isBox(x, y) < 0;
    // play backwards: random walks, sometimes pulling a box behind us
    const pulls = this.v.pulls || 40;
    for (let s = 0; s < pulls * 8; s++) {
      const d = pick(Object.values(DIR));
      const nx = p[0] + d[0], ny = p[1] + d[1];
      if (!free(nx, ny)) continue;
      const bi = isBox(p[0] - d[0], p[1] - d[1]);
      if (bi >= 0 && Math.random() < 0.7) boxes[bi] = [p[0], p[1]];
      p = [nx, ny];
    }
    const off = boxes.filter((b) => !goals.some((g) => g[0] === b[0] && g[1] === b[1])).length;
    if (off < Math.min(tries > 200 ? 1 : 2, nBox)) return false;
    this.wall = wall; this.goals = goals; this.boxes = boxes; this.p = p;
    this.cs = Math.min(24, Math.floor(300 / w), Math.floor(256 / h));
    this.ox = Math.round((320 - w * this.cs) / 2); this.oy = Math.round((272 - h * this.cs) / 2);
    return true;
  }
  onPress(b) {
    if (b === 'select') { const s = JSON.parse(this.start); this.p = s.p; this.boxes = s.boxes; this.history = []; this.moves = 0; this.sfx('back'); return; }
    if (b === 'b') { const s = this.history.pop(); if (s) { const o = JSON.parse(s); this.p = o.p; this.boxes = o.boxes; this.moves--; this.sfx('back'); } return; }
    const d = DIR[b]; if (!d) return;
    const nx = this.p[0] + d[0], ny = this.p[1] + d[1];
    if (this.wall[ny][nx]) return;
    const bi = this.boxes.findIndex((q) => q[0] === nx && q[1] === ny);
    const snap = JSON.stringify({ p: this.p, boxes: this.boxes });
    if (bi >= 0) {
      const bx = nx + d[0], by = ny + d[1];
      if (this.wall[by][bx] || this.boxes.some((q) => q[0] === bx && q[1] === by)) return;
      this.boxes = this.boxes.map((q, i) => (i === bi ? [bx, by] : q));
      this.sfx(this.goals.some((g) => g[0] === bx && g[1] === by) ? 'eat' : 'move');
    } else this.sfx('turn');
    this.history.push(snap);
    this.p = [nx, ny]; this.moves++;
    if (this.boxes.every((q) => this.goals.some((g) => g[0] === q[0] && g[1] === q[1]))) {
      this.addScore(Math.max(50, 400 - this.moves * 2) * this.level, 160, 120, COL.gold); this.sfx('levelup');
      this.level++;
      if (this.level > (this.v.levels || 5)) return this.end(true, 'WAREHOUSE DONE');
      this.build();
    }
  }
  step() {}
  hud() { return { mid: `LV${this.level} MOVES ${this.moves}` }; }
  draw(g) {
    const { cs, ox, oy } = this;
    for (let y = 0; y < this.h; y++) for (let x = 0; x < this.w; x++) {
      const px = ox + x * cs, py = oy + y * cs;
      if (this.wall[y][x]) { block(g, px, py, cs, cs, '#7a4a2a', '#2a1a10'); rect(g, px + 2, py + cs / 2, cs - 4, 1, '#5a3a1e'); }
      else rect(g, px, py, cs, cs, (x + y) % 2 ? '#3a3026' : '#352b22');
    }
    for (const [x, y] of this.goals) { rect(g, ox + x * cs + cs / 2 - 3, oy + y * cs + cs / 2 - 3, 6, 6, COL.gold); }
    for (const [x, y] of this.boxes) {
      const on = this.goals.some((q) => q[0] === x && q[1] === y);
      block(g, ox + x * cs + 2, oy + y * cs + 2, cs - 4, cs - 4, on ? COL.mint : '#c99a5b');
      rect(g, ox + x * cs + 4, oy + y * cs + cs / 2, cs - 8, 1, '#00000055'); rect(g, ox + x * cs + cs / 2, oy + y * cs + 4, 1, cs - 8, '#00000055');
    }
    const [x, y] = this.p;
    block(g, ox + x * cs + 4, oy + y * cs + 3, cs - 8, cs - 6, COL.blue);
    rect(g, ox + x * cs + cs / 2 - 3, oy + y * cs + 7, 2, 2, COL.white); rect(g, ox + x * cs + cs / 2 + 1, oy + y * cs + 7, 2, 2, COL.white);
  }
}
export default module(Sokoban);
